{
  "milestone": "C15 T3 P2Z",
  "date": "2026-10-29",
  "status": "offline engineering research; real trusted host and Windows unverified",
  "blocked_gates": [
    {
      "id": "P2Z-HOST-01",
      "description": "Real independent host key custody, protected anchor store, atomic durable CAS, one-time reconcile proof, consent, conversation isolation, epoch revocation",
      "status": "deferred"
    },
    {
      "id": "P2Z-WIN-02",
      "description": "Windows x86-64 NTFS exclusive file/link semantics, file and directory flushing, same-profile process contention, ACL and reparse point checks",
      "status": "not run on Windows"
    },
    {
      "id": "P2Z-CRASH-03",
      "description": "Windows process kill, installed-host restart, power-loss in disposable VM with durable host anchor",
      "status": "Linux subprocess simulation only"
    },
    {
      "id": "P2Z-ROT-04",
      "description": "Actual per-profile key enrollment and epoch rotation, old journal archival/retention and revocation recovery",
      "status": "preflight only"
    },
    {
      "id": "P2Z-RECONCILE-05",
      "description": "Manual host-authorized resolution of corrupt/multiple tails and partial temp records without unsanctioned deletion",
      "status": "unsupported, fail closed"
    },
    {
      "id": "P2Z-RESOURCE-06",
      "description": "Windows sustained-load disk quota, fsync p95/p99, memory, security and plaintext journal retention review",
      "status": "deferred"
    },
    {
      "id": "P2Z-SENSOR-07",
      "description": "Calibrated real 3D sensor accuracy, camera movement and independent mapping baselines, T1/T2 uncertainties",
      "status": "deferred"
    }
  ],
  "preserve": [
    "P2Y baseline",
    "P2X cache parity benchmark",
    "R1 tracking performance baseline",
    "T3 earlier synthetic negative cases",
    "all earlier Cognitum checkpoint and benchmark backlogs"
  ],
  "note": "Cognitum P2Z does not change Lu or GitHub"
}

